create or replace function public.schedule_relation_unary_violates_v1(p_type text,p_params jsonb,p_day smallint,p_start smallint,p_end smallint) returns boolean language plpgsql immutable set search_path=public as $$ declare t text:=upper(coalesce(p_type,''));v int;days int[];periods int[];day_ok boolean;begin if t='STARTS_DAY' then v:=coalesce(nullif(p_params->>'first_period','')::int,1);return p_start<>v;elsif t='ENDS_DAY' then if nullif(p_params->>'last_period','') is null then return false;end if;return p_end<>(p_params->>'last_period')::int;end if;select coalesce(array_agg(x::int),'{}') into days from jsonb_array_elements_text(coalesce(p_params->'days','[]'::jsonb))x;select coalesce(array_agg(x::int),'{}') into periods from jsonb_array_elements_text(coalesce(p_params->'periods','[]'::jsonb))x;if cardinality(days)=0 and cardinality(periods)=0 then return false;end if;day_ok:=cardinality(days)=0 or p_day=any(days);if t='PREFERRED_START' then return not(day_ok and(cardinality(periods)=0 or p_start=any(periods)));elsif t='PREFERRED_SLOT' then return not(day_ok and(cardinality(periods)=0 or not exists(select 1 from generate_series(p_start::int,p_end::int)q where not q=any(periods))));elsif t='FORBIDDEN_SLOT' then return day_ok and(cardinality(periods)=0 or exists(select 1 from generate_series(p_start::int,p_end::int)q where q=any(periods)));end if;return false;end $$;
create or replace function public.schedule_relation_set_violation_v1(p_relation_id uuid,p_scenario_id uuid default null) returns integer language plpgsql stable security definer set search_path=public as $$ declare t text;p jsonb;m int:=1;n int:=0;cnt int:=0;days int:=0;minp int;maxp int;occupied int:=0;rooms int:=0;begin select upper(relation_type),parameters into t,p from public.schedule_planning_relations where id=p_relation_id and active and tenant_row_allowed(institution_code);if t is null then return 0;end if;m:=coalesce(nullif(coalesce(p->>'max',p->>'value'),'')::int,1);if t='GROUPED' then with a as(select * from public.get_schedule_relation_selected_activities_v1(p_relation_id,p_scenario_id)),slots as(select distinct weekday,q from a cross join lateral generate_series(start_p::int,end_p::int)q) select count(*),count(distinct weekday),min(start_p),max(end_p),(select count(*) from slots) into cnt,days,minp,maxp,occupied from a;if cnt<=1 then return 0;end if;if days<>1 then return greatest(1,cnt-1);end if;return case when maxp-minp+1=occupied then 0 else 1 end;elsif t='MAX_DIFFERENT_ROOMS' then select count(distinct classroom_id) into rooms from public.get_schedule_relation_selected_activities_v1(p_relation_id,p_scenario_id) where classroom_id is not null;return greatest(0,rooms-m);elsif t='MAX_OCCUPIED_SLOTS' then with a as(select * from public.get_schedule_relation_selected_activities_v1(p_relation_id,p_scenario_id)),slots as(select distinct weekday,q from a cross join lateral generate_series(start_p::int,end_p::int)q where(coalesce(jsonb_array_length(p->'days'),0)=0 or exists(select 1 from jsonb_array_elements_text(p->'days')d where d::int=weekday))and(coalesce(jsonb_array_length(p->'periods'),0)=0 or exists(select 1 from jsonb_array_elements_text(p->'periods')x where x::int=q)))select count(*) into occupied from slots;return greatest(0,occupied-m);elsif t='MAX_SIMULTANEOUS' then with a as(select * from public.get_schedule_relation_selected_activities_v1(p_relation_id,p_scenario_id)),slots as(select weekday,q,count(*)c from a cross join lateral generate_series(start_p::int,end_p::int)q where(coalesce(jsonb_array_length(p->'days'),0)=0 or exists(select 1 from jsonb_array_elements_text(p->'days')d where d::int=weekday))and(coalesce(jsonb_array_length(p->'periods'),0)=0 or exists(select 1 from jsonb_array_elements_text(p->'periods')x where x::int=q))group by weekday,q)select coalesce(sum(greatest(c-m,0)),0)::int into n from slots;return n;end if;return 0;end $$;
